"""Guardian-owned reusable SVG history chart with event and phase overlays."""
from html import escape

def render_history_html(*, configuration_path: str, maintenance_path: str, timeline_path: str) -> str:
    config, maintenance, timeline = [escape(v, quote=True) for v in (configuration_path, maintenance_path, timeline_path)]
    html = r'''<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Guardian Zeitverläufe</title><style>
:root{color-scheme:light dark;--blue:#0d47a1;--card:var(--card-background-color,#fff);--grid:#78909c38;--axis:#607d8b;--marker:#ef6c00}*{box-sizing:border-box}body{margin:0;font:14px system-ui;background:var(--primary-background-color,#f5f6f8);color:var(--primary-text-color,#222)}header{padding:18px 22px;background:var(--blue);color:#fff}nav{display:flex;gap:8px;flex-wrap:wrap;margin-top:12px}nav a{color:#fff;text-decoration:none;padding:8px 12px;border:1px solid #ffffff66;border-radius:8px}nav a.active{background:#fff;color:var(--blue)}main{max-width:1280px;margin:auto;padding:16px}.panel,.chart-card{background:var(--card);padding:16px;border-radius:12px;box-shadow:0 1px 5px #0002;margin-bottom:14px}.controls{display:grid;grid-template-columns:minmax(135px,1.2fr) 68px 95px minmax(145px,1.2fr) minmax(145px,1.2fr) minmax(115px,1fr) minmax(115px,1fr) max-content;gap:8px;align-items:end}.controls label{display:grid;gap:4px;min-width:0}input,select,button{font:inherit;padding:9px;border:1px solid #8888;border-radius:8px;background:transparent;color:inherit;min-width:0}button{cursor:pointer}.primary{background:#1976d2;color:#fff;border:0;white-space:nowrap}.chart-wrap{position:relative;width:100%;height:380px;overflow:hidden}svg{width:100%;height:100%;display:block}.grid{stroke:var(--grid);stroke-width:1;vector-effect:non-scaling-stroke}.axis{stroke:var(--axis);stroke-width:1;vector-effect:non-scaling-stroke}.tick{fill:currentColor;font-size:12px}.series{fill:none;stroke-width:2;vector-effect:non-scaling-stroke;transition:opacity .12s,stroke-width .12s}.series.multi{stroke-width:1.5;opacity:.76}.series.focus{stroke-width:3;opacity:1}.phase-label{fill:currentColor;font-size:11px;opacity:.65}.marker{stroke:var(--marker);stroke-width:1.5;vector-effect:non-scaling-stroke}.wrench{fill:var(--marker);font-size:18px;cursor:pointer}.marker-hit{stroke:transparent;stroke-width:20;cursor:pointer}.tooltip{position:absolute;pointer-events:none;padding:7px 9px;border-radius:7px;background:#111e;color:#fff;white-space:nowrap;z-index:4}.detail{margin-top:10px;padding:10px;border-left:4px solid var(--marker);background:#ef6c0014}.legend{display:flex;gap:9px;flex-wrap:wrap;margin:8px 0}.legend button{padding:5px 8px;background:transparent}.swatch{display:inline-block;width:12px;height:3px;margin-right:5px;vertical-align:middle}.empty{position:absolute;inset:0;display:grid;place-content:center;text-align:center;padding:20px;font-size:16px;pointer-events:none}.muted{opacity:.72}.error{padding:10px;border-left:4px solid #d32f2f;background:#d32f2f18}[hidden]{display:none!important}
@media(max-width:980px){.controls{grid-template-columns:repeat(4,minmax(0,1fr))}.controls button{width:100%}}@media(max-width:620px){main{padding:10px}.controls{grid-template-columns:repeat(2,minmax(0,1fr))}.controls label:nth-of-type(4),.controls label:nth-of-type(5),.controls button{grid-column:span 2}.chart-wrap{height:310px}.tick{font-size:11px}}@media(max-width:390px){.panel,.chart-card{padding:10px}.controls{grid-template-columns:1fr}.controls label:nth-of-type(4),.controls label:nth-of-type(5),.controls button{grid-column:1}.chart-wrap{height:285px}}
</style></head><body><header><h1>Guardian Battery</h1><div>Messverläufe mit zeitlichem Maintenance-Kontext</div><nav><a href="__CONFIG__">Konfiguration</a><a href="__MAINTENANCE__">Maintenance-Logbuch</a><a href="__TIMELINE__">Verlauf</a><a class="active" href="history">Zeitverläufe</a></nav></header><main>
<section class="panel"><h2>Guardian-Zeitverlauf</h2><p>Messwerte, Phasen und Marker bleiben getrennte Projektionen. Die Ansicht zeigt zeitliche Korrelation, keine Kausalität.</p><form id="controls" class="controls"><label>Messgröße<select id="metric"><option value="soc">SOC [%]</option><option value="current">Strom [A]</option><option value="cell_voltage">Zellspannung [V]</option><option value="cell_temperature">Zelltemperatur [°C]</option></select></label><label>Modul<select id="module"></select></label><label>Zelle<select id="cell"><option value="">Alle Zellen / Modulebene</option></select></label><label>Von<input id="from" type="datetime-local" required></label><label>Bis<input id="to" type="datetime-local" required></label><label>Aktivitätsfilter<select id="active"><option value="true">Nur aktive</option><option value="all">Alle</option><option value="false">Nur nicht aktive</option></select></label><label>Phasen anzeigen<select id="show-phases"><option value="on">EIN</option><option value="off">AUS</option></select></label><button class="primary">Zeitfenster laden</button></form></section>
<section class="chart-card"><h2 id="chart-title">Zeitverlauf</h2><div id="message"></div><div id="legend" class="legend"></div><div id="chart" class="chart-wrap" role="img" aria-label="Guardian Messverlauf"><svg id="plot"><g id="phase-layer"></g><g id="grid-layer"></g><g id="axis-layer"></g><g id="series-layer"></g><g id="marker-layer"></g><g id="interaction-layer"></g></svg><div id="empty" class="empty" hidden><strong>Keine Messdaten in diesem Zeitfenster</strong><span class="muted">Zeitraum oder Modul prüfen. Es werden keine Ersatzwerte erzeugt.</span></div><div id="tooltip" class="tooltip" hidden></div></div><section id="marker-detail" class="detail" hidden><strong id="marker-title"></strong><div id="marker-meta" class="muted"></div><p id="marker-summary"></p><a id="marker-link">Maintenance-Eintrag öffnen</a></section></section></main><script>
const byId=id=>document.getElementById(id),NS='http://www.w3.org/2000/svg',UNITS={soc:'%',current:'A',cell_voltage:'V',cell_temperature:'°C'},COLORS=['#1565c0','#c62828','#2e7d32','#6a1b9a','#ef6c00','#00838f','#ad1457','#558b2f','#4527a0','#0277bd','#9e9d24','#5d4037','#7b1fa2','#00695c','#d84315'],PHASE_COLORS={charge:'#42a5f522',discharge:'#ef535022',rest:'#90a4ae18',low:'#ffb3001c',high:'#ab47bc1c',unknown:'#78909c10'};let currentData=null;
function svg(tag,attrs={}){const n=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))n.setAttribute(k,String(v));return n}function clear(id){byId(id).replaceChildren()}function localInput(d){const p=n=>String(n).padStart(2,'0');return `${d.getFullYear()}-${p(d.getMonth()+1)}-${p(d.getDate())}T${p(d.getHours())}:${p(d.getMinutes())}`}function options(id,max){for(let n=1;n<=max;n++)byId(id).insertAdjacentHTML('beforeend',`<option>${n}</option>`)}function query(){const q=new URLSearchParams({metric:byId('metric').value,module_number:byId('module').value,from:new Date(byId('from').value).toISOString(),to:new Date(byId('to').value).toISOString(),active:byId('active').value,analysis_mode:'historical'});if(!byId('cell').disabled&&byId('cell').value)q.set('cell_number',byId('cell').value);return q}function text(x,y,v,a='middle'){const n=svg('text',{x,y,class:'tick','text-anchor':a});n.textContent=v;return n}function niceStep(r,c){const raw=r/Math.max(1,c),p=10**Math.floor(Math.log10(raw||1)),f=raw/p;return(f<=1?1:f<=2?2:f<=5?5:10)*p}function display(m,v){return m==='cell_voltage'?v/1000:v}function decimals(m,s){if(m==='soc')return 0;if(m==='cell_voltage')return Math.max(2,Math.min(3,Math.ceil(-Math.log10(s||.01))));return s<1?1:0}function timeLabel(ms,span){return new Intl.DateTimeFormat('de-DE',span>1728e5?{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'}:{hour:'2-digit',minute:'2-digit'}).format(new Date(ms))}function exact(ms){return new Intl.DateTimeFormat('de-DE',{dateStyle:'medium',timeStyle:'medium'}).format(new Date(ms))}
function showMarker(marker){byId('marker-detail').hidden=false;byId('marker-title').textContent=marker.title;const parts=[exact(Date.parse(marker.timestamp)),marker.module_number?'Position '+marker.module_number:null,marker.module_serial?'Seriennummer '+marker.module_serial:null,marker.cell_number?'Zelle '+marker.cell_number:null].filter(Boolean);byId('marker-meta').textContent=parts.join(' · ');byId('marker-summary').textContent=marker.summary||'';byId('marker-link').href=marker.deep_link}
function render(data){currentData=data;const wrap=byId('chart'),width=Math.max(320,Math.round(wrap.clientWidth)),height=Math.max(250,Math.round(wrap.clientHeight)),margin={left:64,right:20,top:28,bottom:50},plotW=width-margin.left-margin.right,plotH=height-margin.top-margin.bottom,metric=data.series.metric,unit=UNITS[metric],points=data.series.points.map(p=>({...p,time:Date.parse(p.timestamp),display:display(metric,p.value)})),start=Date.parse(data.window.from),end=Date.parse(data.window.to),span=Math.max(1,end-start);byId('plot').setAttribute('viewBox',`0 0 ${width} ${height}`);for(const id of ['phase-layer','grid-layer','axis-layer','series-layer','marker-layer','interaction-layer'])clear(id);clear('legend');byId('empty').hidden=points.length>0;if(!points.length){const x=time=>margin.left+(time-start)/span*plotW,tickCount=Math.max(2,Math.min(8,Math.floor(plotW/110))),emptyMarkerTop=height-margin.bottom-30;for(const interval of (byId('show-phases').value==='on'?data.phase_analysis?.intervals||[]:[])){const x1=Math.max(margin.left,x(Date.parse(interval.from))),x2=Math.min(width-margin.right,x(Date.parse(interval.to))),primary=interval.phases?.[0]||'unknown';if(x2>=x1)byId('phase-layer').append(svg('rect',{x:x1,y:margin.top,width:Math.max(1,x2-x1),height:plotH,fill:PHASE_COLORS[primary]||PHASE_COLORS.unknown}))}for(let index=0;index<=tickCount;index++){const time=start+span*index/tickCount,px=x(time);byId('grid-layer').append(svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'grid'}));byId('axis-layer').append(text(px,height-margin.bottom+23,timeLabel(time,span)))}byId('axis-layer').append(svg('line',{x1:margin.left,y1:height-margin.bottom,x2:width-margin.right,y2:height-margin.bottom,class:'axis'}));for(const marker of data.overlays){const px=x(Date.parse(marker.timestamp));byId('marker-layer').append(svg('line',{x1:px,y1:emptyMarkerTop,x2:px,y2:height-margin.bottom,class:'marker'}));const icon=svg('text',{x:px,y:emptyMarkerTop+18,class:'wrench','text-anchor':'middle'});icon.textContent='🔧';icon.onclick=()=>showMarker(marker);byId('marker-layer').append(icon);const hit=svg('line',{x1:px,y1:emptyMarkerTop,x2:px,y2:height-margin.bottom,class:'marker-hit',tabindex:0,'aria-label':'Maintenance: '+marker.title});hit.onclick=()=>showMarker(marker);hit.onkeydown=event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();showMarker(marker)}};byId('interaction-layer').append(hit)}byId('tooltip').hidden=true;return}let min=Math.min(...points.map(p=>p.display)),max=Math.max(...points.map(p=>p.display));if(min===max){const pad=Math.abs(min)*.05||1;min-=pad;max+=pad}const step=niceStep(max-min,5),yMin=Math.floor(min/step)*step,yMax=Math.ceil(max/step)*step||step,x=t=>margin.left+(t-start)/span*plotW,y=v=>margin.top+(yMax-v)/(yMax-yMin)*plotH;
for(const interval of (byId('show-phases').value==='on'?data.phase_analysis?.intervals||[]:[])){const x1=Math.max(margin.left,x(Date.parse(interval.from))),x2=Math.min(width-margin.right,x(Date.parse(interval.to))),primary=interval.phases?.[0]||'unknown';if(x2>=x1){byId('phase-layer').append(svg('rect',{x:x1,y:margin.top,width:Math.max(1,x2-x1),height:plotH,fill:PHASE_COLORS[primary]||PHASE_COLORS.unknown}));if(x2-x1>55){const label=text((x1+x2)/2,margin.top+13,interval.phase);label.setAttribute('class','phase-label');byId('phase-layer').append(label)}}}
for(let v=yMin;v<=yMax+step/2;v+=step){const py=y(v);byId('grid-layer').append(svg('line',{x1:margin.left,y1:py,x2:width-margin.right,y2:py,class:'grid'}));byId('axis-layer').append(text(margin.left-8,py+4,`${v.toFixed(decimals(metric,step))} ${unit}`,'end'))}const tickCount=Math.max(2,Math.min(8,Math.floor(plotW/110)));for(let i=0;i<=tickCount;i++){const t=start+span*i/tickCount,px=x(t);byId('grid-layer').append(svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'grid'}));byId('axis-layer').append(text(px,height-margin.bottom+23,timeLabel(t,span)))}byId('axis-layer').append(svg('line',{x1:margin.left,y1:margin.top,x2:margin.left,y2:height-margin.bottom,class:'axis'}),svg('line',{x1:margin.left,y1:height-margin.bottom,x2:width-margin.right,y2:height-margin.bottom,class:'axis'}));
const groups=new Map();for(const p of points){const key=p.cell_number||0;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)}for(const [key,group] of groups){const path=svg('path',{d:group.map((p,i)=>`${i?'L':'M'}${x(p.time).toFixed(2)},${y(p.display).toFixed(2)}`).join(' '),class:'series'+(groups.size>1?' multi':''),'data-cell':key||'',stroke:COLORS[(key||1)-1]});byId('series-layer').append(path);if(key){const button=document.createElement('button');const swatch=document.createElement('span');swatch.className='swatch';swatch.style.background=COLORS[key-1];button.append(swatch,document.createTextNode('Zelle '+key));button.onmouseenter=()=>path.classList.add('focus');button.onmouseleave=()=>path.classList.remove('focus');byId('legend').append(button)}}
for(const marker of data.overlays){const px=x(Date.parse(marker.timestamp));byId('marker-layer').append(svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'marker'}));const icon=svg('text',{x:px,y:margin.top+17,class:'wrench','text-anchor':'middle'});icon.textContent='🔧';icon.onclick=()=>showMarker(marker);byId('marker-layer').append(icon);const hit=svg('line',{x1:px,y1:margin.top,x2:px,y2:height-margin.bottom,class:'marker-hit',tabindex:0,'aria-label':'Maintenance: '+marker.title});hit.onclick=()=>showMarker(marker);hit.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showMarker(marker)}};byId('interaction-layer').append(hit)}const tooltip=byId('tooltip');wrap.onpointermove=e=>{const rect=wrap.getBoundingClientRect(),mx=(e.clientX-rect.left)/rect.width*width,t=start+(mx-margin.left)/plotW*span,p=points.reduce((a,b)=>Math.abs(b.time-t)<Math.abs(a.time-t)?b:a);tooltip.textContent=`${exact(p.time)} · ${p.display.toFixed(decimals(metric,step))} ${unit}${p.cell_number?' · Zelle '+p.cell_number:''}`;tooltip.hidden=false;tooltip.style.left=Math.min(rect.width-220,Math.max(4,e.clientX-rect.left+10))+'px';tooltip.style.top='8px'};wrap.onpointerleave=()=>tooltip.hidden=true}
async function load(e){e?.preventDefault();clear('message');byId('marker-detail').hidden=true;try{const r=await fetch('api/history/series?'+query()),data=await r.json();if(!r.ok)throw Error(data.error?.message||'Zeitverlauf nicht verfügbar');byId('chart-title').textContent=byId('metric').selectedOptions[0].textContent;render(data)}catch(error){clear('message');const box=document.createElement('div');box.className='error';box.textContent=error.message;byId('message').append(box);currentData=null}}function metricChanged(){const cell=byId('metric').value.startsWith('cell_');byId('cell').disabled=!cell;if(!cell)byId('cell').value=''}options('module',6);options('cell',15);const end=new Date(),start=new Date(end-864e5);byId('from').value=localInput(start);byId('to').value=localInput(end);byId('metric').onchange=metricChanged;byId('show-phases').onchange=()=>currentData&&render(currentData);metricChanged();byId('controls').onsubmit=load;new ResizeObserver(()=>currentData&&render(currentData)).observe(byId('chart'));load();
</script></body></html>'''
    return html.replace('__CONFIG__', config).replace('__MAINTENANCE__', maintenance).replace('__TIMELINE__', timeline)
